begin;set local search_path=public,extensions;select plan(4);
create temporary table p06_compose_observed(key text primary key,value jsonb);grant select,insert on p06_compose_observed to authenticated;grant usage on schema extensions to authenticated;


update public.question_rules set current_draft_version_id='fb151000-0000-0000-0000-000000000002'where id='fb150000-0000-0000-0000-000000000002';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.save_catalog_rule_draft('fb150000-0000-0000-0000-000000000002','fb151000-0000-0000-0000-000000000002','{"condition_ast":{"operator":"EQ","question_version_id":"fb141000-0000-0000-0000-000000000001","value":true},"actions":[{"type":"HUMAN_REVIEW"}],"dependency_graph":{},"priority":20,"sensitive":false}','Downgrade de recette',1,1,'source-sensitive-denied')$$,'42501','CATALOG_SENSITIVE_MFA_REQUIRED','an AAL1 owner cannot remove source sensitivity to bypass MFA');
select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.save_catalog_rule_draft('fb150000-0000-0000-0000-000000000002','fb151000-0000-0000-0000-000000000002','{"condition_ast":{"operator":"EQ","question_version_id":"fb141000-0000-0000-0000-000000000001","value":true},"actions":[{"type":"HUMAN_REVIEW"}],"dependency_graph":{},"priority":20,"sensitive":false}','Révision authentifiée',1,1,'source-sensitive-allowed')$$,'the same owner can create the reviewed new draft after MFA');
select throws_ok($$select public.create_catalog_questionnaire('fb120000-0000-0000-0000-000000000001','fb130000-0000-0000-0000-000000000001','MISSING_SENSITIVITY','{"title_fr":"Test questionnaire","title_ar":"استبيان اختبار","description_fr":"Description complète","description_ar":"وصف كامل","audience":"CLIENT","engine_version":"1.0","policy_version":"P06","section_key":"GENERAL","section_label_fr":"Général","section_label_ar":"عام"}','Création invalide','questionnaire-missing-sensitivity')$$,'22023','INVALID_CATALOG_QUESTIONNAIRE','questionnaire creation cannot silently default an omitted sensitivity flag');
reset role;
select is((select count(*)from public.question_rule_versions where rule_id='fb150000-0000-0000-0000-000000000002'),2::bigint,'denied sensitivity downgrade creates no partial rule version');
select *from finish();rollback;
